steps.raw:
SELECT 100.0 * SUM(CASE WHEN m.label = '+' AND a.element = 'cl' THEN 1 ELSE 0 END) / COUNT(DISTINCT CASE WHEN m.label = '+' THEN m.molecule_id END) AS percentage
FROM molecule m
LEFT JOIN atom a ON m.molecule_id = a.molecule_id;

SELECT COALESCE(SUM(CASE WHEN users.DisplayName = 'Mornington' THEN posts.ViewCount ELSE 0 END), 0) - COALESCE(SUM(CASE WHEN users.DisplayName = 'Amos' THEN posts.ViewCount ELSE 0 END), 0) AS view_count_difference
FROM posts
JOIN users ON posts.OwnerUserId = users.Id;

SELECT (SUM(CASE WHEN a.id = 2 AND s.gender_id = 2 THEN 1 ELSE 0 END) * 100.0) / NULLIF(SUM(CASE WHEN a.id = 2 THEN 1 ELSE 0 END), 0) AS female_percentage
FROM superhero AS s
JOIN alignment AS a ON s.alignment_id = a.id;

SELECT (SUM(CASE WHEN preferred_foot = 'left' THEN 1 ELSE 0 END) * 100.0) / COUNT(player_fifa_api_id) AS percentage_left_foot
FROM Player
WHERE CAST(strftime('%Y', birthday) AS INTEGER) BETWEEN 1987 AND 1992;

SELECT 100.0 * SUM(CASE WHEN m.position = 'Member' AND maj.major_name = 'Business' THEN 1 ELSE 0 END) / COUNT(m.member_id) AS percentage
FROM member AS m
LEFT JOIN major AS maj ON m.link_to_major = maj.major_id;
